// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(c));
        Reverter reverter = new Reverter();
        vm.deal(address(c), 1 ether);
        bool ok = true;
        try c.withdrawAll(address(reverter)) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
